public class MainActivity extends Activity {
    private static final int BG=0xff08111f, PANEL=0xff142338, TEXT=0xffe7eef8, MUTED=0xffa1b4cc, ACCENT=0xff3de3d1;
    private static final int PERM=100, EXPORT=101, NA=RadioMath.NA;
    private final Handler handler=new Handler(Looper.getMainLooper());
    private TelephonyManager tm; private DisplayCallback cb; private PhoneStateListener oldCb;
    private boolean foreground=false, busy=false; private int generation=0, displayOverride=-1, displayBase=-1;
    private List<Cell> cells=new ArrayList<>(); private JSONArray history=new JSONArray();
    private TextView status, net, metrics, detail, recommendations, comparison, historyText, agentText, modelText;
    private int autoRemaining=0; private long autoStarted=0, autoDeadline=0; private Button autoButton; private boolean modelBusy=false; private Button modelButton; private EditText modelName;
    private LinearLayout cellList; private EditText place; private Button save; private Plot plot;
    private String notice="Aucune acquisition"; private int subscription=-1;
    private final Runnable tick=new Runnable(){public void run(){if(foreground){refresh();handler.postDelayed(this,7000);}}};
    private static class Cell {
        String tech, bands, operator; int channel=NA,pci=NA,tac=NA,bw=NA,rsrp=NA,rsrq=NA,snr=NA,role=0; long id=Long.MAX_VALUE, stamp; boolean registered;
        double mhz=Double.NaN;
        boolean serving(){return registered||role==CellInfo.CONNECTION_PRIMARY_SERVING||role==CellInfo.CONNECTION_SECONDARY_SERVING;}
        String roleName(){if(role==CellInfo.CONNECTION_PRIMARY_SERVING)return "Principale";if(role==CellInfo.CONNECTION_SECONDARY_SERVING)return "Secondaire";if(registered)return "Enregistrée";return "Voisine / rôle non confirmé";}
        long age(){return stamp<=0?Long.MAX_VALUE:Math.max(0,SystemClock.elapsedRealtime()-stamp);}
        boolean fresh(){return age()<=20000;}
        String key(){return tech+":"+channel+":"+pci+":"+id;}
    }
    @Override public void onCreate(Bundle b){super.onCreate(b);load();build();render();}
    @Override protected void onStart(){super.onStart();foreground=true;setup();handler.post(tick);}
    @Override protected void onStop(){foreground=false;stopAuto();generation++;busy=false;handler.removeCallbacksAndMessages(null);unregister();super.onStop();}
    private int dp(float n){return (int)(getResources().getDisplayMetrics().density*n+.5f);}
    private LinearLayout column(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);return l;}
    private GradientDrawable bg(int color,int radius){GradientDrawable g=new GradientDrawable();g.setColor(color);g.setCornerRadius(dp(radius));return g;}
    private TextView label(LinearLayout l,String s,int size,int color){TextView t=new TextView(this);t.setText(s);t.setTextColor(color);t.setTextSize(size);t.setPadding(0,dp(4),0,dp(4));l.addView(t);return t;}
    private TextView heading(LinearLayout l,String s){TextView t=label(l,s,19,ACCENT);t.setTypeface(null,Typeface.BOLD);return t;}
    private LinearLayout panel(LinearLayout parent){LinearLayout l=column();l.setBackground(bg(PANEL,16));l.setPadding(dp(16),dp(12),dp(16),dp(12));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=dp(12);parent.addView(l,p);return l;}
    private Button action(LinearLayout l,String s,Runnable r){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setOnClickListener(v->r.run());l.addView(b,new LinearLayout.LayoutParams(-1,-2));return b;}
    private void build(){
        ScrollView sc=new ScrollView(this);sc.setFillViewport(true);sc.setBackgroundColor(BG);LinearLayout root=column();root.setPadding(dp(16),dp(12),dp(16),dp(24));sc.addView(root);setContentView(sc);
        label(root,"STUDIO NIKO  /  RADIO LAB",12,ACCENT);TextView title=label(root,"RF Metrology Pro",30,TEXT);title.setTypeface(null,Typeface.BOLD);label(root,"V4 • mesures modem 4G / 5G • métrologie réseau",13,MUTED);
        action(root,"Métrologie réseau · sécurité · rapports",()->startActivity(new Intent(this,DashboardActivity.class)));
        LinearLayout p=panel(root);heading(p,"01  /  RADIO EN DIRECT");status=label(p,"",13,MUTED);net=label(p,"",17,TEXT);metrics=label(p,"",23,TEXT);detail=label(p,"",14,MUTED);action(p,"Autoriser / actualiser",()->{if(!hasPerm())ask();else refresh();});action(p,"Réglages du réseau mobile",()->openSettings(Settings.ACTION_WIRELESS_SETTINGS));action(p,"Activer la localisation Android",()->openSettings(Settings.ACTION_LOCATION_SOURCE_SETTINGS));
        p=panel(root);heading(p,"02  /  CELLULES OBSERVÉES");cellList=column();p.addView(cellList);label(p,"PCI seul ≠ identification unique du relais. Les porteuses masquées par le modem ne sont pas inventées.",12,MUTED);action(p,"Cartoradio — carte officielle",()->link("https://www.cartoradio.fr/"));action(p,"Lancer un test nPerf externe",()->link("https://www.nperf.com/fr/"));
        p=panel(root);heading(p,"03  /  OPTIMISATION");recommendations=label(p,"",15,TEXT);place=new EditText(this);place.setSingleLine(true);place.setTextColor(TEXT);place.setHintTextColor(MUTED);place.setHint("Emplacement : fenêtre, salon, jardin…");place.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(60)});p.addView(place);save=action(p,"Enregistrer la mesure actuelle",this::saveSample);autoButton=action(p,"Mesurer automatiquement cet emplacement",this::startAuto);label(p,"Comparer au moins 3 mesures fraîches par emplacement et par bande, idéalement à plusieurs horaires.",12,MUTED);
        p=panel(root);heading(p,"04  /  HISTORIQUE LOCAL");plot=new Plot();p.addView(plot,new LinearLayout.LayoutParams(-1,dp(145)));comparison=label(p,"",14,TEXT);historyText=label(p,"",12,MUTED);action(p,"Exporter les mesures en CSV",this::export);action(p,"Effacer l’historique",()->new AlertDialog.Builder(this).setMessage("Supprimer toutes les mesures locales ?").setNegativeButton("Annuler",null).setPositiveButton("Effacer",(d,w)->{history=new JSONArray();persist();renderHistory();}).show());
        p=panel(root);heading(p,"05  /  CENTRE MULTI-AGENTS");agentText=label(p,"",14,TEXT);label(p,"Agents déterministes : calculs et règles locaux, sans modèle génératif. Actualisation automatique avec les relevés.",12,MUTED);modelName=new EditText(this);modelName.setSingleLine(true);modelName.setTextColor(TEXT);modelName.setText("local");modelName.setHint("Nom du modèle local");p.addView(modelName);modelButton=action(p,"Consulter une IA locale (facultatif)",this::askModel);modelText=label(p,"Serveur llama.cpp ou compatible sur 127.0.0.1:8080 ; connexion USB adb reverse possible. Aucun appel par défaut.",13,MUTED);
        p=panel(root);heading(p,"06  /  TRANSPARENCE");label(p,"Pas de GPS enregistré, pas de compte, pas de publicité, pas d’envoi automatique des mesures. L’IA facultative reçoit uniquement les indicateurs radio anonymisés via une connexion locale explicitement déclenchée. Android exige la localisation précise pour exposer les cellules. L’application ne modifie pas les bandes radio et ne détecte ni personnes ni signaux ISAC. Les liens ouvrent des services externes.",14,MUTED);
    }
    private void openSettings(String action){try{startActivity(new Intent(action));}catch(Exception e){toast("Réglage indisponible");}}
    private void link(String url){try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(url)));}catch(Exception e){toast("Aucun navigateur disponible");}}
    private boolean hasPerm(){return checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)==PackageManager.PERMISSION_GRANTED;}
    private boolean phonePerm(){return checkSelfPermission(Manifest.permission.READ_PHONE_STATE)==PackageManager.PERMISSION_GRANTED;}
    private void ask(){requestPermissions(new String[]{Manifest.permission.ACCESS_FINE_LOCATION,Manifest.permission.ACCESS_COARSE_LOCATION,Manifest.permission.READ_PHONE_STATE},PERM);}
    @Override public void onRequestPermissionsResult(int req,String[] p,int[] g){super.onRequestPermissionsResult(req,p,g);if(req==PERM){setup();refresh();}}
    private void unregister(){if(tm!=null){try{if(Build.VERSION.SDK_INT>=31&&cb!=null)tm.unregisterTelephonyCallback(cb);if(oldCb!=null)tm.listen(oldCb,PhoneStateListener.LISTEN_NONE);}catch(Exception ignored){}}cb=null;oldCb=null;}
    private void setup(){unregister();displayOverride=-1;displayBase=-1;subscription=SubscriptionManager.getDefaultDataSubscriptionId();TelephonyManager base=getSystemService(TelephonyManager.class);tm=base==null?null:(SubscriptionManager.isValidSubscriptionId(subscription)?base.createForSubscriptionId(subscription):base);if(tm==null||!phonePerm())return;
        try{if(Build.VERSION.SDK_INT>=31){cb=new DisplayCallback();tm.registerTelephonyCallback(getMainExecutor(),cb);}else{oldCb=new PhoneStateListener(){@Override public void onDisplayInfoChanged(TelephonyDisplayInfo i){display(i);}};tm.listen(oldCb,PhoneStateListener.LISTEN_DISPLAY_INFO_CHANGED);}}catch(Exception ignored){}
    }
    private class DisplayCallback extends TelephonyCallback implements TelephonyCallback.DisplayInfoListener{public void onDisplayInfoChanged(TelephonyDisplayInfo i){display(i);}}
    private void display(TelephonyDisplayInfo i){if(!foreground)return;displayOverride=i.getOverrideNetworkType();displayBase=i.getNetworkType();render();}
    private void refresh(){if(!foreground||busy)return;if(autoRemaining>0&&SystemClock.elapsedRealtime()>autoDeadline){stopAuto();toast("Session terminée : données insuffisantes ou délai dépassé.");}if(subscription!=SubscriptionManager.getDefaultDataSubscriptionId()){generation++;cells.clear();setup();}if(!hasPerm()){cells.clear();notice="Autorisation de localisation précise nécessaire.";render();return;}LocationManager lm=getSystemService(LocationManager.class);if(lm!=null&&!lm.isLocationEnabled()){cells.clear();notice="Localisation Android désactivée.";render();return;}if(tm==null){notice="Modem indisponible";render();return;}
        final int g=++generation;busy=true;notice="Demande au modem…";render();
        try{tm.requestCellInfoUpdate(getMainExecutor(),new TelephonyManager.CellInfoCallback(){@Override public void onCellInfo(List<CellInfo> list){if(!foreground||g!=generation)return;busy=false;receive(list,"Réponse modem");}@Override public void onError(int code,Throwable t){if(!foreground||g!=generation)return;busy=false;cached("Erreur modem "+code);}});handler.postDelayed(()->{if(foreground&&g==generation&&busy){busy=false;generation++;cached("Délai modem dépassé");}},6500);}catch(Exception e){busy=false;cached("Acquisition indisponible");}
    }
    private void cached(String msg){try{receive(tm.getAllCellInfo(),msg+" • cache Android");}catch(Exception e){cells.clear();notice=msg+" • aucune donnée";render();}}
    private void receive(List<CellInfo> list,String source){ArrayList<Cell> result=new ArrayList<>();if(list!=null)for(CellInfo i:list){try{Cell c=decode(i);if(c!=null)result.add(c);}catch(RuntimeException ignored){}}
        result.sort(Comparator.comparing((Cell c)->!c.serving()).thenComparing(c->c.role!=CellInfo.CONNECTION_PRIMARY_SERVING).thenComparing(c->c.tech));cells=result;notice=source+" • "+cells.size()+" cellule(s) LTE/NR";render();autoCapture();}
    private Cell decode(CellInfo i){Cell c=new Cell();c.role=i.getCellConnectionStatus();c.registered=i.isRegistered();c.stamp=i.getTimestampMillis();
        if(i instanceof CellInfoLte){CellInfoLte l=(CellInfoLte)i;CellIdentityLte a=l.getCellIdentity();CellSignalStrengthLte s=l.getCellSignalStrength();c.tech="LTE";c.channel=a.getEarfcn();c.pci=a.getPci();c.tac=a.getTac();c.id=a.getCi()==NA?Long.MAX_VALUE:a.getCi();c.bw=a.getBandwidth();c.rsrp=s.getRsrp();c.rsrq=s.getRsrq();c.snr=s.getRssnr();c.mhz=RadioMath.lteMHz(c.channel);c.bands=bands(a.getBands(),"B");if(c.bands.equals("—")&&RadioMath.band(c.channel)!=NA)c.bands="B"+RadioMath.band(c.channel);c.operator=plmn(a.getMccString(),a.getMncString());}
        else if(i instanceof CellInfoNr){CellInfoNr n=(CellInfoNr)i;CellIdentityNr a=(CellIdentityNr)n.getCellIdentity();CellSignalStrengthNr s=(CellSignalStrengthNr)n.getCellSignalStrength();c.tech="NR";c.channel=a.getNrarfcn();c.pci=a.getPci();c.tac=a.getTac();c.id=a.getNci();c.rsrp=s.getSsRsrp();c.rsrq=s.getSsRsrq();c.snr=s.getSsSinr();c.mhz=RadioMath.nrMHz(c.channel);c.bands=bands(a.getBands(),"n");c.operator=plmn(a.getMccString(),a.getMncString());}else return null;return c;}
    private String bands(int[] a,String prefix){if(a==null||a.length==0)return "—";StringJoiner j=new StringJoiner("/");for(int b:a)j.add(prefix+b);return j.toString();}
    private String plmn(String mcc,String mnc){return mcc==null||mnc==null?"—":mcc+"-"+mnc;}
    private Cell primary(){for(Cell c:cells)if(c.fresh()&&c.role==CellInfo.CONNECTION_PRIMARY_SERVING&&c.rsrp!=NA)return c;for(Cell c:cells)if(c.fresh()&&c.registered&&c.rsrp!=NA)return c;return null;}
    private String transport(){ConnectivityManager cm=getSystemService(ConnectivityManager.class);if(cm==null)return "inconnu";NetworkCapabilities n=cm.getNetworkCapabilities(cm.getActiveNetwork());if(n==null)return "aucun";if(n.hasTransport(NetworkCapabilities.TRANSPORT_VPN))return "VPN";if(n.hasTransport(NetworkCapabilities.TRANSPORT_WIFI))return "Wi-Fi";if(n.hasTransport(NetworkCapabilities.TRANSPORT_CELLULAR))return "mobile";return "autre";}
    private String displayText(){if(displayBase==TelephonyManager.NETWORK_TYPE_NR)return "NR déclaré par Android";if(displayOverride==3||displayOverride==4||displayOverride==5)return "Indication 5G (≠ preuve d’une porteuse NR active)";if(displayOverride==1||displayOverride==2)return "Indication LTE évoluée";if(displayBase==TelephonyManager.NETWORK_TYPE_LTE)return "LTE";return "Non communiqué";}
    private void render(){if(status==null)return;status.setText(notice+"\nTransport Internet : "+transport());String op="—";try{if(tm!=null)op=tm.getNetworkOperatorName()+" / "+tm.getNetworkOperator();}catch(Exception ignored){}net.setText(op+"\n"+displayText());Cell c=primary();int nr=0,lte=0,secondary=0;for(Cell x:cells)if(x.fresh()&&x.serving()){if(x.tech.equals("NR"))nr++;else lte++;if(x.role==CellInfo.CONNECTION_SECONDARY_SERVING)secondary++;}
        metrics.setText(c==null?"RSRP  —  /  aucune mesure fraîche":"RSRP  "+c.rsrp+" dBm  •  "+RadioMath.quality(c.rsrp));detail.setText((c==null?"RSRQ —  |  SNR/SINR —":c.tech+" "+c.bands+"  |  RSRQ "+RadioMath.value(c.rsrq," dB")+"  |  "+(c.tech.equals("NR")?"SINR ":"SNR ")+RadioMath.value(c.snr," dB"))+"\nCellules servantes exposées : LTE "+lte+" / NR "+nr+" / secondaires "+secondary+"\n"+(nr>0?"NR servant rapporté par le modem.":"Aucune cellule NR servante fraîche rapportée ; 5G non confirmée.")+(secondary>0?"\nUne cellule secondaire est rapportée ; agrégation exacte non garantie.":""));
        cellList.removeAllViews();if(cells.isEmpty())label(cellList,"Aucune cellule LTE/NR disponible",14,MUTED);for(Cell x:cells){LinearLayout p=panel(cellList);p.setBackground(bg(0xff0b192b,10));label(p,x.tech+"  "+x.bands+"  •  "+x.roleName(),16,ACCENT);label(p,"PLMN "+x.operator+"  |  PCI "+RadioMath.value(x.pci,"")+"  |  TAC "+RadioMath.value(x.tac,"")+"\nCell ID "+(x.id==Long.MAX_VALUE?"—":x.id)+"  |  "+(x.tech.equals("LTE")?"EARFCN ":"NR-ARFCN ")+RadioMath.value(x.channel,"")+"\n"+(x.tech.equals("LTE")?"Centre DL ":"Référence NR ")+RadioMath.fmt(x.mhz)+" MHz  |  BW "+(x.bw==NA?"—":RadioMath.fmt(x.bw/1000.0)+" MHz")+"\nRSRP "+RadioMath.value(x.rsrp," dBm")+"  |  RSRQ "+RadioMath.value(x.rsrq," dB")+"  |  SNR/SINR "+RadioMath.value(x.snr," dB")+"\nÂge : "+(x.age()==Long.MAX_VALUE?"inconnu":x.age()/1000+" s")+(x.fresh()?"":" • ancien"),13,TEXT);}
        save.setEnabled(c!=null);String tip="Désactive le Wi-Fi pour tester le débit mobile. Garde le mode réseau automatique et compare 4G / 5G depuis les réglages.";if(c!=null){if(c.rsrp< -105)tip+="\nSignal faible : essaie près d’une fenêtre, plus haut ou dehors.";if(c.snr!=NA&&c.snr<5)tip+="\nRapport signal/bruit bas : teste un autre emplacement ou horaire.";if(c.rsrp>=-105&&c.snr!=NA&&c.snr>=10)tip+="\nSignal exploitable : confirme par plusieurs tests de débit et de stabilité.";}recommendations.setText(tip);renderHistory();}
    private void startAuto(){if(autoRemaining>0){stopAuto();return;}if(place.getText().toString().trim().isEmpty()){place.setError("Indique un emplacement");return;}if(!hasPerm()){ask();return;}autoRemaining=3;autoStarted=SystemClock.elapsedRealtime();autoDeadline=autoStarted+90000;place.setEnabled(false);autoButton.setText("Arrêter • 3 relevés attendus");refresh();}
    private void stopAuto(){autoRemaining=0;if(place!=null)place.setEnabled(true);if(autoButton!=null)autoButton.setText("Mesurer automatiquement cet emplacement");}
    private void autoCapture(){if(autoRemaining<=0)return;if(SystemClock.elapsedRealtime()>autoDeadline){stopAuto();return;}Cell c=primary();if(c==null||c.stamp<autoStarted)return;JSONObject prev=history.optJSONObject(history.length()-1);String old=prev==null?"":prev.optString("key")+":"+prev.optLong("stamp");if(old.equals(c.key()+":"+c.stamp))return;saveSample();JSONObject end=history.optJSONObject(history.length()-1);String key=end==null?"":end.optString("key")+":"+end.optLong("stamp");if(!key.equals(old)&&key.equals(c.key()+":"+c.stamp)){autoRemaining--;if(autoRemaining==0){stopAuto();toast("Session automatique terminée");}else autoButton.setText("Arrêter • "+autoRemaining+" relevé(s) attendu(s)");}}
    private void saveSample(){Cell c=primary();if(c==null){toast("Aucune mesure fraîche");return;}String loc=place.getText().toString().trim();if(loc.isEmpty()){place.setError("Indique un emplacement");return;}String key=c.key();for(int i=history.length()-1;i>=0;i--){JSONObject o=history.optJSONObject(i);if(o!=null&&o.optString("key").equals(key)&&o.optLong("stamp")==c.stamp&&System.currentTimeMillis()-o.optLong("time")<60000){toast("Mesure déjà enregistrée ; attends un nouveau relevé modem.");return;}}
        try{JSONObject o=new JSONObject();o.put("time",System.currentTimeMillis());o.put("stamp",c.stamp);o.put("age_s",c.age()/1000);o.put("place",loc);o.put("tech",c.tech);o.put("band",c.bands);o.put("operator",c.operator);o.put("key",key);o.put("channel",c.channel);o.put("pci",c.pci);o.put("cell_id",c.id==Long.MAX_VALUE?JSONObject.NULL:c.id);o.put("rsrp",c.rsrp);o.put("rsrq",c.rsrq);o.put("snr",c.snr);history.put(o);while(history.length()>1000)history.remove(0);persist();renderHistory();toast("Mesure enregistrée localement");}catch(JSONException e){toast("Enregistrement impossible");}}
    private void load(){try{history=new JSONArray(getPreferences(MODE_PRIVATE).getString("history","[]"));}catch(Exception ignored){history=new JSONArray();}}
    private void persist(){getPreferences(MODE_PRIVATE).edit().putString("history",history.toString()).apply();}
    private void renderHistory(){if(comparison==null)return;Map<String,List<Integer>> groups=new TreeMap<>();StringBuilder last=new StringBuilder();for(int i=0;i<history.length();i++){JSONObject o=history.optJSONObject(i);if(o==null)continue;String k=o.optString("operator")+" • "+o.optString("tech")+" "+o.optString("band")+" • "+o.optString("place");groups.computeIfAbsent(k,x->new ArrayList<>()).add(o.optInt("rsrp"));if(i>=history.length()-6)last.append(o.optString("place")).append(" / ").append(o.optString("band")).append(" / ").append(o.optInt("rsrp")).append(" dBm\n");}StringBuilder s=new StringBuilder("Médianes RSRP par opérateur, technologie, bande et lieu :\n");for(Map.Entry<String,List<Integer>> e:groups.entrySet())s.append(e.getKey()).append(" : ").append(RadioMath.fmt(RadioMath.median(e.getValue()))).append(" dBm (n=").append(e.getValue().size()).append(")").append(e.getValue().size()<3?" • provisoire":"").append("\n");comparison.setText(groups.isEmpty()?"Aucune mesure sauvegardée":s.toString());historyText.setText(history.length()+" mesure(s) • 6 dernières\n"+last);plot.invalidate();renderAgents();}
    private List<AgentEngine.Reading> liveReadings(){List<AgentEngine.Reading> a=new ArrayList<>();for(Cell c:cells)a.add(new AgentEngine.Reading(c.tech,c.bands,c.operator,"",c.rsrp,c.rsrq,c.snr,c.age(),c.serving(),""));return a;}
    private boolean icon5g(){return displayBase==TelephonyManager.NETWORK_TYPE_NR||displayOverride==3||displayOverride==4||displayOverride==5;}
    private void renderAgents(){if(agentText==null)return;List<AgentEngine.Reading> h=new ArrayList<>();for(int i=0;i<history.length();i++){JSONObject o=history.optJSONObject(i);if(o==null)continue;h.add(new AgentEngine.Reading(o.optString("tech"),o.optString("band"),o.optString("operator"),o.optString("place"),o.optInt("rsrp",NA),o.optInt("rsrq",NA),o.optInt("snr",NA),0,true,o.optString("key")+":"+o.optLong("stamp")+":"+(o.optLong("time")-o.optLong("stamp"))/60000));}agentText.setText(AgentEngine.run(liveReadings(),h,transport(),icon5g()).display());}
    private void askModel(){if(modelBusy)return;String name=modelName.getText().toString().trim();if(name.isEmpty()||name.length()>100){modelName.setError("Nom du modèle requis (100 caractères max)");return;}String context=AgentEngine.modelContext(liveReadings(),transport(),icon5g());new AlertDialog.Builder(this).setTitle("IA locale facultative").setMessage("Envoyer seulement les mesures radio courantes, sans lieu ni identifiant, au serveur que tu contrôles sur 127.0.0.1:8080 ? La réponse est consultative et non vérifiée.").setNegativeButton("Annuler",null).setPositiveButton("Analyser",(d,w)->{modelBusy=true;modelButton.setEnabled(false);modelText.setText("Inférence locale demandée…");new Thread(()->{String msg;try{msg="IA locale — proposition non vérifiée :\n"+LocalModel.analyze(context,name);}catch(Exception e){msg="IA indisponible : vérifier le serveur local et le nom du modèle. Le diagnostic déterministe reste opérationnel.";}final String result=msg;runOnUiThread(()->{if(isDestroyed())return;modelBusy=false;modelButton.setEnabled(true);modelText.setText(result);});}).start();}).show();}
    private void export(){Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.setType("text/csv");i.addCategory(Intent.CATEGORY_OPENABLE);i.putExtra(Intent.EXTRA_TITLE,"niko-radio-mesures.csv");try{startActivityForResult(i,EXPORT);}catch(Exception e){toast("Export indisponible");}}
    private String csv(String s){if(s.startsWith("=")||s.startsWith("+")||s.startsWith("-")||s.startsWith("@")||s.startsWith("\t"))s="'"+s;return "\""+s.replace("\"","\"\"")+"\"";}
    @Override protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(req!=EXPORT||result!=RESULT_OK||data==null||data.getData()==null)return;String[] keys={"time","age_s","place","operator","tech","band","channel","pci","cell_id","rsrp","rsrq","snr"};try(OutputStream out=getContentResolver().openOutputStream(data.getData(),"wt")){if(out==null)throw new IOException();StringBuilder s=new StringBuilder(String.join(",",keys)+"\n");for(int i=0;i<history.length();i++){JSONObject o=history.getJSONObject(i);StringJoiner j=new StringJoiner(",");for(String k:keys){Object v=o.opt(k);j.add(v==null||v==JSONObject.NULL||v.toString().equals(String.valueOf(NA))?"":v instanceof Number?v.toString():csv(v.toString()));}s.append(j).append('\n');}out.write(s.toString().getBytes(StandardCharsets.UTF_8));toast("CSV exporté");}catch(Exception e){toast("Échec de l’export");}}
    private void toast(String s){Toast.makeText(this,s,Toast.LENGTH_SHORT).show();}
    private class Plot extends View{Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);Plot(){super(MainActivity.this);setContentDescription("Historique RSRP des 30 dernières mesures, toutes bandes");}protected void onDraw(Canvas c){super.onDraw(c);float w=getWidth(),h=getHeight(),left=dp(40),right=w-dp(8),top=dp(12),bottom=h-dp(20);p.setTextSize(dp(10));p.setStrokeWidth(dp(1));for(int v:new int[]{-120,-100,-80,-60}){float y=top+(-60-v)/60f*(bottom-top);p.setColor(MUTED);c.drawText(""+v,0,y+dp(3),p);p.setColor(0xff2a3d55);c.drawLine(left,y,right,y,p);}int start=Math.max(0,history.length()-30),n=history.length()-start;for(int i=0;i<n;i++){JSONObject o=history.optJSONObject(start+i);if(o==null)continue;float x=n<=1?(left+right)/2:left+i*(right-left)/(n-1);float y=top+(-60-Math.max(-120,Math.min(-60,o.optInt("rsrp"))))/60f*(bottom-top);p.setColor(ACCENT);c.drawCircle(x,y,dp(3),p);}p.setColor(MUTED);c.drawText("RSRP (dBm) • toutes bandes • 30 derniers relevés",left,bottom+dp(15),p);}}
}
